select data into existing from public.ea_records where id=e->>'id' for update;
if existing is not null and existing<>e then raise exception 'Election differs %',e->>'id'; end if;
insert into public.ea_records(id,kind,data,updated) values(e->>'id','world_election',e,now()) on conflict(id) do update set data=excluded.data,updated=now(); end loop;
update public.ea_records set data=jsonb_set(data,'{coverageNote}',to_jsonb('National Storting elections from 1815 through 2025 and both constituent assemblies of 1814. Before political parties emerged, tables report non-partisan representatives without invented party votes. Modern votes, elected representatives and turnout use Statistics Norway national data; shared historical votes and joint-list allocations are distinguished. Exact dates or polling ranges are used where established, otherwise year precision. The Odelsting and Lagting were internal divisions of the elected Storting, not separate national elections.'::text)),updated=now() where id='world-country-no';
end $import$;
commit;
